// Local reminders (scheduled on the phone, no server) live in zzz/notifications.ts.
import * as Notifications from 'expo-notifications'
import { useCallback, useEffect, useState } from 'react'
import { AppState, Linking, Platform } from 'react-native'

const PROJECT_ID = '__BLOXKS_PUSH_PROJECT_ID__'
const BUNDLE_ID = '__BLOXKS_PUSH_BUNDLE_ID__'
const REGISTER_URL = 'https://bloxks.app/api/v1/push/register'
const OPENED_URL = 'https://bloxks.app/api/v1/push/opened'
// Version of this file, sent at registration: 2 = reports notification opens.
const FILE_VERSION = 2

/** True only in a store build on iPhone (Android push arrives later). */
export const PUSH_IS_AVAILABLE = Platform.OS === 'ios' && !PROJECT_ID.startsWith('__')

export type PushPermission = 'granted' | 'denied' | 'undetermined'

export type PushRegistration =
  | { ok: true; token: string }
  | { ok: false; reason: 'unavailable' | 'denied' | 'not_asked' | 'error'; message: string; permission?: PushPermission }

// Every native call goes through `call`: a member missing from the runtime (web
// preview, Expo Go, an older SDK) returns the fallback instead of throwing
// "X is not a function" and taking the whole app down.
type AnyFn = (...args: never[]) => unknown
function call<T>(name: string, fallback: T, ...args: unknown[]): T {
  try {
    const fn = (Notifications as unknown as Record<string, unknown>)[name]
    return typeof fn === 'function' ? ((fn as AnyFn)(...(args as never[])) as T) : fallback
  } catch {
    return fallback
  }
}

// Same handler as zzz/notifications.ts (whichever is imported first, same result).
call('setNotificationHandler', undefined, {
  handleNotification: async () => ({
    shouldShowBanner: true,
    shouldShowList: true,
    shouldPlaySound: true,
    shouldSetBadge: false,
  }),
})

// A network or native call that never answers must not freeze the app: after
// TIMEOUT_MS the fallback is returned instead. Never throws.
const TIMEOUT_MS = 10000
function within<T>(work: () => Promise<T>, fallback: T): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const late = new Promise<T>((resolve) => { timer = setTimeout(() => resolve(fallback), TIMEOUT_MS) })
  const run = Promise.resolve().then(work).catch(() => fallback)
  return Promise.race([run, late]).finally(() => clearTimeout(timer))
}

type DeviceToken = { data?: unknown } | null
function deviceToken(): Promise<DeviceToken> {
  return within(() => call<Promise<DeviceToken>>('getDevicePushTokenAsync', Promise.resolve(null)), null)
}

async function post(path: 'register' | 'unregister', body: Record<string, unknown>): Promise<boolean> {
  return within(async () => {
    const res = await fetch(REGISTER_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ...body, projectId: PROJECT_ID, bundleId: BUNDLE_ID, platform: Platform.OS, action: path, v: FILE_VERSION }),
    })
    return res.ok
  }, false)
}

async function readPermission(ask: boolean): Promise<PushPermission> {
  type Perm = { granted?: boolean; canAskAgain?: boolean; status?: string } | null
  const current = await call<Promise<Perm>>('getPermissionsAsync', Promise.resolve(null))
  if (current?.granted) return 'granted'
  const blocked = current?.canAskAgain === false || current?.status === 'denied'
  if (!ask || blocked) return blocked ? 'denied' : 'undetermined'
  const asked = await call<Promise<Perm>>('requestPermissionsAsync', Promise.resolve(null))
  return asked?.granted ? 'granted' : 'denied'
}

/** Current permission, without asking. Show the pre-permission screen only when 'undetermined'. */
export async function getPushPermission(): Promise<PushPermission> {
  try { return await readPermission(false) } catch { return 'undetermined' }
}

const UNAVAILABLE = 'Notifications allowed. They arrive in the published app (TestFlight / App Store), not in the preview or Expo Go. · Notifications autorisées : elles arrivent dans l’app publiée (TestFlight / App Store), pas dans l’aperçu ni Expo Go.'
const DENIED = 'Notifications refusées — active-les dans les réglages. · Notifications denied — enable them in settings.'

async function registerDevice(opts: { userRef?: string | null; accessToken?: string | null; locale?: string | null }): Promise<PushRegistration> {
  const device = await deviceToken()
  const token = device?.data ? String(device.data) : ''
  if (!token) return { ok: false, reason: 'unavailable', message: 'Push token unavailable on this device.', permission: 'granted' }
  // The token proves who is signed in: Bloxks checks it with the app's Supabase before binding userRef.
  const ok = await post('register', { token, userRef: opts.userRef ?? null, accessToken: opts.accessToken ?? null, locale: opts.locale ?? null })
  if (!ok) return { ok: false, reason: 'error', message: 'Registration failed — the app will retry at next launch.', permission: 'granted' }
  return { ok: true, token }
}

/**
 * Shows the system permission prompt (first time only), then registers this
 * device with Bloxks. Call it from the "Allow" button of the pre-permission
 * screen. `userRef` (the signed-in user's id) enables targeted sends, only with
 * `accessToken` (their Supabase session token): Bloxks verifies it belongs to that
 * user, otherwise the device is registered without user (announcements only).
 */
export async function registerForPush(opts: { userRef?: string | null; accessToken?: string | null; locale?: string | null } = {}): Promise<PushRegistration> {
  try {
    const permission = await readPermission(true)
    if (permission !== 'granted') return { ok: false, reason: 'denied', message: DENIED, permission }
    if (!PUSH_IS_AVAILABLE) return { ok: false, reason: 'unavailable', message: UNAVAILABLE, permission }
    return await registerDevice(opts)
  } catch (e) {
    return { ok: false, reason: 'error', message: e instanceof Error ? e.message : String(e) }
  }
}

/**
 * Silent re-registration for every app start: refreshes the device and binds it
 * to the signed-in user. NEVER shows the system prompt — when the user was not
 * asked yet it answers `not_asked` and does nothing.
 */
export async function refreshPushRegistration(opts: { userRef?: string | null; accessToken?: string | null; locale?: string | null } = {}): Promise<PushRegistration> {
  try {
    const permission = await readPermission(false)
    if (permission === 'undetermined') return { ok: false, reason: 'not_asked', message: 'Permission not requested yet.', permission }
    if (permission === 'denied') return { ok: false, reason: 'denied', message: DENIED, permission }
    if (!PUSH_IS_AVAILABLE) return { ok: false, reason: 'unavailable', message: UNAVAILABLE, permission }
    return await registerDevice(opts)
  } catch (e) {
    return { ok: false, reason: 'error', message: e instanceof Error ? e.message : String(e) }
  }
}

/**
 * State + action for a Settings "Notifications" row or switch. `permission` is
 * null while loading, then 'granted' | 'denied' | 'undetermined', re-read when
 * the app comes back to the foreground (the user may have changed it in the
 * phone settings). `enable()` asks the first time, and opens the phone
 * settings when notifications were refused (iOS never asks twice).
 */
export function usePushPermission(opts: { userRef?: string | null; accessToken?: string | null; locale?: string | null } = {}): [PushPermission | null, () => Promise<PushRegistration>] {
  const [permission, setPermission] = useState<PushPermission | null>(null)
  useEffect(() => {
    let alive = true
    const read = () => { getPushPermission().then((p) => { if (alive) setPermission(p) }).catch(() => {}) }
    read()
    let sub: { remove?: () => void } | undefined
    try { sub = AppState.addEventListener('change', (state: string) => { if (state === 'active') read() }) } catch {}
    return () => { alive = false; try { sub?.remove?.() } catch {} }
  }, [])
  const enable = useCallback(async (): Promise<PushRegistration> => {
    const current = await getPushPermission()
    if (current === 'denied') {
      try { if (typeof Linking.openSettings === 'function') await Linking.openSettings() } catch {}
      return { ok: false, reason: 'denied', message: DENIED, permission: 'denied' }
    }
    const result = await registerForPush(opts)
    setPermission(await getPushPermission())
    return result
  }, [opts.userRef, opts.accessToken, opts.locale])
  return [permission, enable]
}

/** Stops server-sent notifications for this device (e.g. on sign-out). Never throws. */
export async function unregisterFromPush(): Promise<void> {
  if (!PUSH_IS_AVAILABLE) return
  try {
    const device = await deviceToken()
    if (device?.data) await post('unregister', { token: String(device.data) })
  } catch {}
}

type AnyRecord = Record<string, unknown>
const isRecord = (v: unknown): v is AnyRecord => !!v && typeof v === 'object' && !Array.isArray(v)

// Custom data of a tapped notification. Bloxks sends it at the top level of the
// Apple payload: depending on the SDK it is in content.data, in its "body", or
// only in trigger.payload — merge all of them, without Apple's "aps".
function notificationData(response: Notifications.NotificationResponse | null | undefined): AnyRecord {
  const request = (response?.notification?.request ?? {}) as { content?: { data?: unknown }; trigger?: unknown }
  const payload = isRecord(request.trigger) && isRecord((request.trigger as AnyRecord).payload) ? ((request.trigger as AnyRecord).payload as AnyRecord) : {}
  const rawData = request.content?.data
  const data = isRecord(rawData) ? rawData : {}
  const merged: AnyRecord = {
    ...payload,
    ...(isRecord(payload.body) ? payload.body : {}),
    ...(isRecord(data.body) ? data.body : {}),
    ...data,
  }
  delete merged.aps
  if (isRecord(payload.body) || isRecord(data.body)) delete merged.body
  return merged
}

// Open tracking (counts shown in the Bloxks Notifications tab): reports each
// tapped notification once, by itself, whether or not the app listens to taps.
const reportedOpens = new Set<string>()
async function reportOpen(response: Notifications.NotificationResponse | null | undefined): Promise<void> {
  try {
    if (!response) return
    const sendId = notificationData(response)._bx
    if (typeof sendId !== 'string' || reportedOpens.has(sendId)) return
    reportedOpens.add(sendId)
    const device = await deviceToken()
    if (!device?.data) return
    await within(() => fetch(OPENED_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ projectId: PROJECT_ID, sendId, token: String(device.data) }),
    }), null)
  } catch {}
}
if (PUSH_IS_AVAILABLE) {
  call('addNotificationResponseReceivedListener', null, reportOpen)
  Promise.resolve(call<Promise<Notifications.NotificationResponse | null> | null>('getLastNotificationResponseAsync', null))
    .then(reportOpen)
    .catch(() => {})
}

// Taps already handed to the app, by notification identifier: the listener and
// the "last response" (tap that launched the app) report the same tap, and a
// remounted screen reads that last response again — each tap is handled once.
const handledTaps = new Set<string>()

/**
 * Calls `cb` with the notification's data when the user taps it — including the
 * tap that launched the app. Each tap reaches the app once, even across remounts.
 * Returns the unsubscribe function.
 */
export function onNotificationOpened(cb: (data: Record<string, unknown>) => void): () => void {
  // Preview / Expo Go: no notification can open the app, nothing to listen to.
  if (!PUSH_IS_AVAILABLE) return () => {}
  const read = (response: Notifications.NotificationResponse | null | undefined) => {
    try {
      if (!response) return
      const id = response.notification?.request?.identifier
      if (typeof id === 'string' && id) {
        if (handledTaps.has(id)) return
        handledTaps.add(id)
      }
      try { cb(notificationData(response)) } finally {
        Promise.resolve(call<Promise<void> | undefined>('clearLastNotificationResponseAsync', undefined)).catch(() => {})
      }
    } catch {}
  }
  const sub = call<{ remove?: () => void } | null>('addNotificationResponseReceivedListener', null, read)
  Promise.resolve(call<Promise<Notifications.NotificationResponse | null> | null>('getLastNotificationResponseAsync', null))
    .then(read)
    .catch(() => {})
  return () => {
    try { sub?.remove?.() } catch {}
  }
}
